style.css:
@-moz-document domain("youtube.com"), domain("www.youtube.com") {
:root {
    --baby-pink: #ffd1e6;
    --baby-pink-dark: #ffb6c1;
  }

  /* ==== TÍTULOS DOS VÍDEOS ==== */
  a#video-title,
  yt-formatted-string#video-title,
  yt-formatted-string#title,
  ytd-video-renderer a#video-title,
  ytd-grid-video-renderer a#video-title,
  ytd-rich-item-renderer a#video-title,
  ytd-rich-grid-media a#video-title,
  ytd-compact-video-renderer #video-title,
  ytd-compact-video-renderer a#video-title,
  h1.title yt-formatted-string,
  ytd-video-primary-info-renderer h1.title yt-formatted-string {
    color: var(--baby-pink) !important;
  }

  /* ==== NOME DO CANAL ==== */
  a[href^="/channel/"],
  a[href^="/c/"],
  a[href^="/user/"],
  ytd-channel-name yt-formatted-string,
  ytd-channel-name a,
  ytd-channel-renderer yt-formatted-string,
  ytd-video-owner-renderer a {
    color: var(--baby-pink) !important;
  }

  /* ==== NOMES NOS COMENTÁRIOS ==== */
  #author-text,
  #author-text span,
  ytd-comment-renderer #author-text,
  ytd-comment-renderer #author-text a,
  ytd-comment-thread-renderer #author-text {
    color: var(--baby-pink) !important;
  }

  /* ==== VISUALIZAÇÕES, DATA, HORA ==== */
  #metadata-line span,
  ytd-video-meta-block #metadata-line span,
  ytd-video-meta-block yt-formatted-string,
  ytd-watch-metadata #info-strings yt-formatted-string {
    color: var(--baby-pink) !important;
  }

  /* ==== LINKS DENTRO DA DESCRIÇÃO ==== */
  ytd-video-secondary-info-renderer a,
  ytd-expander a,
  ytd-watch-metadata a {
    color: var(--baby-pink) !important;
  }

  /* ==== BOTÕES DE INSCRIÇÃO, CURTIR, NÃO CURTIR, COMPARTILHAR, SININHO ==== */
  ytd-subscribe-button-renderer tp-yt-paper-button,
  ytd-subscribe-button-renderer yt-button-shape button,
  ytd-toggle-button-renderer tp-yt-paper-icon-button,
  ytd-toggle-button-renderer yt-icon-button {
    color: var(--baby-pink) !important;
    border-color: var(--baby-pink) !important;
  }

  /* ==== HASHTAGS ==== */
  ytd-video-primary-info-renderer a.yt-simple-endpoint.style-scope.yt-formatted-string,
  ytd-watch-metadata a.yt-simple-endpoint.style-scope.yt-formatted-string {
    color: var(--baby-pink) !important;
  }

  /* ==== MODO ESCURO ==== */
  @media (prefers-color-scheme: dark) {
    a#video-title,
    h1.title yt-formatted-string,
    ytd-channel-name yt-formatted-string,
    #author-text,
    #metadata-line span,
    ytd-video-meta-block yt-formatted-string,
    ytd-watch-metadata #info-strings yt-formatted-string,
    ytd-subscribe-button-renderer tp-yt-paper-button,
    ytd-subscribe-button-renderer yt-button-shape button,
    ytd-toggle-button-renderer tp-yt-paper-icon-button,
    ytd-toggle-button-renderer yt-icon-button,
    ytd-video-primary-info-renderer a.yt-simple-endpoint.style-scope.yt-formatted-string,
    ytd-watch-metadata a.yt-simple-endpoint.style-scope.yt-formatted-string,
    ytd-video-secondary-info-renderer a,
    ytd-expander a,
    ytd-watch-metadata a {
      color: var(--baby-pink-dark) !important;
      border-color: var(--baby-pink-dark) !important;
    }
  }
}
